"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

import {
  getPptxFitScale,
  getPptxResetKey,
  type PptxSlideOverlayProps,
} from "./pptx-viewer-core"
import { PptxErrorBoundary } from "./pptx-viewer-error-boundary"
import { PptxViewerFallback } from "./pptx-viewer-fallback"
import { useRetainedPptxSource } from "./pptx-viewer-hooks"
import { createPptxScrollActivity } from "./pptx-viewer-scroll"
import { PptxSlideScroller } from "./pptx-viewer-slide"
import { PptxToolbar } from "./pptx-viewer-toolbar"
import { usePptxViewportWidth } from "./pptx-viewer-viewport"
import { usePptxVisibleSlide } from "./pptx-viewer-visible-slide"
import { usePptxZoom } from "./pptx-viewer-zoom"

export type { PptxSlideOverlayProps }

/** Client gate without an effect: false during SSR, true after hydration. */
function useIsClient() {
  return React.useSyncExternalStore(
    () => () => {},
    () => true,
    () => false
  )
}

export interface PptxViewerProps {
  /** URL of the .pptx (same-origin or CORS-enabled). */
  src: string
  className?: string
  /** Controlled scale. When omitted, the viewer owns zoom state. */
  scale?: number
  /** Initial uncontrolled scale. When omitted, uncontrolled mode starts fit-width. */
  defaultScale?: number
  /** Called by zoom controls. `null` means return to fit-width mode. */
  onScaleChange?: (scale: number | null) => void
  toolbar?: boolean
  downloadFileName?: string
  /** Render absolutely-positioned overlays, such as bbox citations, on each slide. */
  renderSlideOverlay?: (props: PptxSlideOverlayProps) => React.ReactNode
  /** Fired with the 1-based slide nearest the top of the viewport as you scroll. */
  onVisibleSlideChange?: (slide: number) => void
  /** Fired with scroll progress in [0, 1]. */
  onScrollProgressChange?: (progress: number) => void
  /** Drop the outer border/rounded/background so the viewer fills its container. */
  bare?: boolean
  /** Rendered as a full-width strip directly below the toolbar. */
  header?: React.ReactNode
  /** Rendered as a left rail alongside the scrolling slides. */
  aside?: React.ReactNode
  /**
   * Render slides as soon as they near the viewport, even mid-scroll. Defaults to
   * false: uncached renders wait until scrolling settles.
   */
  eager?: boolean
}

export function PptxViewer(props: PptxViewerProps) {
  const isClient = useIsClient()
  if (!isClient) {
    return <PptxViewerFallback className={props.className} bare={props.bare} />
  }
  return (
    <PptxErrorBoundary
      className={props.className}
      src={props.src}
      bare={props.bare}
      downloadFileName={props.downloadFileName}
      resetKey={getPptxResetKey(props)}
    >
      <React.Suspense
        fallback={
          <PptxViewerFallback className={props.className} bare={props.bare} />
        }
      >
        <PptxViewerContent {...props} />
      </React.Suspense>
    </PptxErrorBoundary>
  )
}

function PptxViewerContent({
  src,
  className,
  scale: controlledScale,
  defaultScale,
  onScaleChange,
  toolbar = true,
  downloadFileName,
  renderSlideOverlay,
  onVisibleSlideChange,
  onScrollProgressChange,
  bare = false,
  header,
  aside,
  eager = false,
}: PptxViewerProps) {
  const source = useRetainedPptxSource(src)

  const [rotation, setRotation] = React.useState(0)
  const scrollActivity = React.useMemo(() => createPptxScrollActivity(), [])
  const { containerRef, viewportWidth } = usePptxViewportWidth()
  const { currentSlide, handleScroll, scrollViewportRef } = usePptxVisibleSlide(
    {
      onScrollProgressChange,
      onVisibleSlideChange,
    }
  )

  const fitScale = getPptxFitScale(viewportWidth, source.baseSize.width)
  const { scaleControlsDisabled, setViewerScale, zoomScale } = usePptxZoom({
    controlledScale,
    defaultScale,
    fitScale,
    onScaleChange,
  })

  const handleViewportScroll = React.useCallback(() => {
    if (!eager) scrollActivity.handleScroll()
    handleScroll()
  }, [eager, handleScroll, scrollActivity])

  return (
    <div
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? "h-full bg-muted/20" : "rounded-xl border bg-muted/30",
        className
      )}
      data-slot="pptx-viewer"
    >
      {toolbar ? (
        <PptxToolbar
          currentSlide={currentSlide}
          slideCount={source.slideCount}
          zoomScale={zoomScale}
          scaleControlsDisabled={scaleControlsDisabled}
          src={src}
          downloadFileName={downloadFileName}
          onZoom={(factor) => setViewerScale(zoomScale * factor)}
          onFitWidth={() => setViewerScale(null)}
          onRotate={() => setRotation((value) => (value + 90) % 360)}
        />
      ) : null}

      <div className="flex min-h-0 flex-1">
        {aside ? (
          <div data-slot="pptx-viewer-aside" className="flex-shrink-0">
            {aside}
          </div>
        ) : null}
        <div className="flex min-h-0 min-w-0 flex-1 flex-col">
          {header ? <div data-slot="pptx-viewer-header">{header}</div> : null}
          <PptxSlideScroller
            source={source}
            zoomScale={zoomScale}
            rotation={rotation}
            eager={eager}
            activity={scrollActivity}
            renderSlideOverlay={renderSlideOverlay}
            containerRef={containerRef}
            viewportRef={scrollViewportRef}
            onScroll={handleViewportScroll}
          />
        </div>
      </div>
    </div>
  )
}

export interface PptxSize {
  width: number
  height: number
}

export interface PptxSlideOverlayProps {
  /** 1-based slide index. */
  slideNumber: number
  /** Rendered slide size in CSS pixels, after scale and rotation. */
  width: number
  height: number
  scale: number
  rotation: number
}

export interface PptxResetInput {
  src: string
  scale?: number
  defaultScale?: number
  eager?: boolean
}

export interface PptxBitmapCacheInput {
  slideIndex: number
  renderScale: number
}

export const DEFAULT_PPTX_SLIDE_SIZE = {
  width: 960,
  height: 720,
} satisfies PptxSize

export function getPptxFitScale(
  containerWidth: number | null,
  baseWidth: number
) {
  if (!containerWidth || !Number.isFinite(containerWidth) || baseWidth <= 0) {
    return 1
  }
  return clamp((containerWidth - 32) / baseWidth, 0.1, 5)
}

export function getPptxResetKey({
  src,
  scale,
  defaultScale,
  eager,
}: PptxResetInput) {
  return [
    src,
    scale ?? defaultScale ?? "fit",
    eager ? "eager" : "settled",
  ].join("\u0000")
}

export function getPptxBitmapCacheKey({
  slideIndex,
  renderScale,
}: PptxBitmapCacheInput) {
  return `${slideIndex}@${Math.round(renderScale * 1000)}`
}

export function getScaledSlideSize(
  baseSize: PptxSize,
  zoomScale: number
): PptxSize {
  return {
    width: baseSize.width * zoomScale,
    height: baseSize.height * zoomScale,
  }
}

export function getVisibleSlideSize(
  slideSize: PptxSize,
  rotation: number
): PptxSize {
  return getRotatedSize(slideSize, rotation)
}

export function getRotatedSize(size: PptxSize, rotation: number): PptxSize {
  const normalized = ((rotation % 360) + 360) % 360
  if (normalized === 90 || normalized === 270) {
    return { width: size.height, height: size.width }
  }
  return size
}

export function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value))
}

import { DEFAULT_PPTX_SLIDE_SIZE, type PptxSize } from "./pptx-viewer-core"

// EMU (English Metric Units) -> CSS px at 96dpi. OOXML measures in EMU;
// 914400 EMU = 1 inch, 96 px = 1 inch, so 9525 EMU = 1 px.
const EMU_PER_PX = 9525

export type PptxXmlParser = (xml: string) => Document | null

export function defaultPptxXmlParser(xml: string): Document | null {
  if (typeof DOMParser === "undefined") return null
  return new DOMParser().parseFromString(xml, "application/xml")
}

export function parsePptxSlideSize(
  xml: string | null | undefined,
  parseXml: PptxXmlParser = defaultPptxXmlParser
): PptxSize {
  if (!xml) {
    return DEFAULT_PPTX_SLIDE_SIZE
  }

  const document = parseXml(xml)
  if (!document) return DEFAULT_PPTX_SLIDE_SIZE

  const parseError = document.getElementsByTagName("parsererror")[0]
  if (parseError) return DEFAULT_PPTX_SLIDE_SIZE

  const slideSize = [...document.getElementsByTagName("*")].find(
    (element) => element.localName === "sldSz"
  )
  if (!slideSize) return DEFAULT_PPTX_SLIDE_SIZE

  const widthEmu = Number(slideSize.getAttribute("cx"))
  const heightEmu = Number(slideSize.getAttribute("cy"))
  if (
    !Number.isFinite(widthEmu) ||
    !Number.isFinite(heightEmu) ||
    widthEmu <= 0 ||
    heightEmu <= 0
  ) {
    return DEFAULT_PPTX_SLIDE_SIZE
  }

  return {
    width: Math.round(widthEmu / EMU_PER_PX),
    height: Math.round(heightEmu / EMU_PER_PX),
  }
}

export interface Disposable {
  dispose(): void
}

export class DisposableLruCache<K, V extends Disposable> {
  private values = new Map<K, V>()

  constructor(private readonly limit: number) {}

  get size() {
    return this.values.size
  }

  get(key: K): V | undefined {
    const value = this.values.get(key)
    if (value !== undefined) {
      this.values.delete(key)
      this.values.set(key, value)
    }
    return value
  }

  set(key: K, value: V) {
    const existing = this.values.get(key)
    if (existing) existing.dispose()
    this.values.delete(key)
    this.values.set(key, value)
    this.evict()
  }

  delete(key: K) {
    const value = this.values.get(key)
    if (!value) return
    this.values.delete(key)
    value.dispose()
  }

  clear() {
    for (const value of this.values.values()) value.dispose()
    this.values.clear()
  }

  private evict() {
    while (this.values.size > this.limit) {
      const oldest = this.values.keys().next().value as K | undefined
      if (oldest === undefined) break
      this.delete(oldest)
    }
  }
}

export class PptxBitmapEntry implements Disposable {
  constructor(readonly bitmap: ImageBitmap) {}

  dispose() {
    this.bitmap.close()
  }
}

"use client"

import * as React from "react"

import { getPptxSource, type PptxSource } from "./pptx-viewer-source"

/** Retains the cached source for the mounted lifetime of the viewer. */
export function useRetainedPptxSource(src: string): PptxSource {
  const source = React.use(getPptxSource(src))
  React.useEffect(() => source.retain(), [source])
  return source
}

import type * as PptxNS from "pptxviewjs"

import { DEFAULT_PPTX_SLIDE_SIZE, type PptxSize } from "./pptx-viewer-core"
import { parsePptxSlideSize } from "./pptx-viewer-presentation"

type PptxModule = typeof PptxNS

interface JSZipLike {
  loadAsync(data: ArrayBuffer): Promise<{
    file(path: string): { async(type: "string"): Promise<string> } | null
  }>
}

export type PptxRendererErrorKind =
  | "fetch_failed"
  | "load_failed"
  | "render_failed"
  | "disposed"

export class PptxRendererError extends Error {
  constructor(
    readonly kind: PptxRendererErrorKind,
    message: string,
    readonly cause?: unknown
  ) {
    super(message)
    this.name = "PptxRendererError"
  }
}

export interface PptxRenderInput {
  slideIndex: number
  canvas: HTMLCanvasElement
  renderScale: number
}

export interface PptxRenderer {
  slideCount: number
  baseSize: PptxSize
  renderSlide(input: PptxRenderInput): Promise<void>
  dispose(): void
}

let pptxModulePromise: Promise<PptxModule> | null = null
let jszipPromise: Promise<JSZipLike> | null = null

function loadPptx(): Promise<PptxModule> {
  if (!pptxModulePromise) pptxModulePromise = import("pptxviewjs")
  return pptxModulePromise
}

function loadJSZip(): Promise<JSZipLike> {
  if (!jszipPromise) {
    jszipPromise = import("jszip").then(
      (mod) =>
        ((mod as { default?: unknown }).default ?? mod) as unknown as JSZipLike
    )
  }
  return jszipPromise
}

async function readSlideSize(buffer: ArrayBuffer): Promise<PptxSize> {
  try {
    const JSZip = await loadJSZip()
    const zip = await JSZip.loadAsync(buffer)
    const xml = await zip.file("ppt/presentation.xml")?.async("string")
    return parsePptxSlideSize(xml)
  } catch {
    return DEFAULT_PPTX_SLIDE_SIZE
  }
}

async function fetchPptx(src: string) {
  let response: Response
  try {
    response = await fetch(src)
  } catch (error) {
    throw new PptxRendererError(
      "fetch_failed",
      "Failed to fetch presentation.",
      error
    )
  }
  if (!response.ok) {
    throw new PptxRendererError(
      "fetch_failed",
      `Failed to load presentation: ${response.status}`
    )
  }
  return response.arrayBuffer()
}

export async function createPptxRenderer(src: string): Promise<PptxRenderer> {
  const buffer = await fetchPptx(src)
  const [pptx, baseSize] = await Promise.all([
    loadPptx(),
    readSlideSize(buffer),
  ])
  const { PPTXViewer } = pptx
  const offscreen = document.createElement("canvas")
  const viewer = new PPTXViewer({
    canvas: offscreen,
    slideSizeMode: "actual",
    autoChartRerenderDelayMs: 0,
  })

  try {
    await viewer.loadFile(buffer)
  } catch (error) {
    throw new PptxRendererError(
      "load_failed",
      "Failed to parse presentation.",
      error
    )
  }

  let disposed = false

  return {
    slideCount: viewer.getSlideCount(),
    baseSize,
    async renderSlide({ slideIndex, canvas, renderScale }) {
      if (disposed) {
        throw new PptxRendererError(
          "disposed",
          "Presentation renderer was disposed."
        )
      }
      try {
        await viewer.renderSlide(slideIndex, canvas, {
          scale: renderScale,
          quality: "high",
        })
      } catch (error) {
        throw new PptxRendererError(
          "render_failed",
          `Failed to render slide ${slideIndex + 1}.`,
          error
        )
      }
    },
    dispose() {
      if (disposed) return
      disposed = true
      viewer.destroy?.()
    },
  }
}

export function resetPptxRendererModules() {
  pptxModulePromise = null
  jszipPromise = null
}

export const PPTX_SCROLL_IDLE_MS = 120

export interface PptxScrollActivity {
  handleScroll(): void
  isScrolling(): boolean
  onIdle(callback: () => void): () => void
}

export function createPptxScrollActivity(
  idleMs = PPTX_SCROLL_IDLE_MS
): PptxScrollActivity {
  let isScrolling = false
  let timer = 0
  const waiters = new Set<() => void>()

  return {
    handleScroll() {
      isScrolling = true
      clearTimeout(timer)
      timer = window.setTimeout(() => {
        isScrolling = false
        const pending = [...waiters]
        waiters.clear()
        for (const callback of pending) callback()
      }, idleMs)
    },
    isScrolling: () => isScrolling,
    onIdle(callback: () => void) {
      waiters.add(callback)
      return () => waiters.delete(callback)
    },
  }
}

"use client"

import * as React from "react"

export function usePptxViewportWidth() {
  const [viewportWidth, setViewportWidth] = React.useState<number | null>(null)

  const containerRef = React.useCallback((element: HTMLDivElement | null) => {
    if (!element) return
    setViewportWidth(element.clientWidth)
    const observer = new ResizeObserver((entries) => {
      for (const entry of entries) {
        setViewportWidth((entry.target as HTMLElement).clientWidth)
      }
    })
    observer.observe(element)
    return () => observer.disconnect()
  }, [])

  return { containerRef, viewportWidth }
}

"use client"

import * as React from "react"

export interface PptxVisibleSlideInput {
  onVisibleSlideChange?: (slide: number) => void
  onScrollProgressChange?: (progress: number) => void
}

export function usePptxVisibleSlide({
  onVisibleSlideChange,
  onScrollProgressChange,
}: PptxVisibleSlideInput) {
  const [currentSlide, setCurrentSlide] = React.useState(1)
  const scrollViewportRef = React.useRef<HTMLDivElement | null>(null)
  const lastReportedSlide = React.useRef(0)

  const handleScroll = React.useCallback(() => {
    const viewport = scrollViewportRef.current
    if (!viewport) return

    const scrollable = viewport.scrollHeight - viewport.clientHeight
    onScrollProgressChange?.(
      scrollable > 0 ? viewport.scrollTop / scrollable : 0
    )

    const rect = viewport.getBoundingClientRect()
    const marker = rect.top + rect.height * 0.2
    const slides = viewport.querySelectorAll<HTMLElement>("[data-slide-number]")
    let visibleSlide = 1
    for (const slide of slides) {
      if (slide.getBoundingClientRect().top <= marker) {
        visibleSlide = Number(slide.dataset.slideNumber)
      } else {
        break
      }
    }

    if (visibleSlide && visibleSlide !== lastReportedSlide.current) {
      lastReportedSlide.current = visibleSlide
      setCurrentSlide(visibleSlide)
      onVisibleSlideChange?.(visibleSlide)
    }
  }, [onScrollProgressChange, onVisibleSlideChange])

  return { currentSlide, handleScroll, scrollViewportRef }
}

"use client"

import * as React from "react"

import { clamp } from "./pptx-viewer-core"

type PptxZoomState =
  | { mode: "fit" }
  | {
      mode: "manual"
      value: number
    }

export interface PptxZoomInput {
  controlledScale?: number
  defaultScale?: number
  fitScale: number
  onScaleChange?: (scale: number | null) => void
}

export function usePptxZoom({
  controlledScale,
  defaultScale,
  fitScale,
  onScaleChange,
}: PptxZoomInput) {
  const [zoomState, setZoomState] = React.useState<PptxZoomState>(() =>
    defaultScale == null
      ? { mode: "fit" }
      : { mode: "manual", value: clamp(defaultScale, 0.25, 5) }
  )

  const isScaleControlled = controlledScale !== undefined
  const zoomScale =
    controlledScale ??
    (zoomState.mode === "manual" ? zoomState.value : fitScale)
  const scaleControlsDisabled = isScaleControlled && !onScaleChange

  const setViewerScale = React.useCallback(
    (nextScale: number | null) => {
      const normalized =
        nextScale == null
          ? null
          : clamp(Number.isFinite(nextScale) ? nextScale : 1, 0.25, 5)
      if (isScaleControlled) {
        onScaleChange?.(normalized)
        return
      }
      setZoomState(
        normalized == null
          ? { mode: "fit" }
          : { mode: "manual", value: normalized }
      )
    },
    [isScaleControlled, onScaleChange]
  )

  return { scaleControlsDisabled, setViewerScale, zoomScale }
}

import {
  DisposableLruCache,
  PptxBitmapEntry,
  type Disposable,
} from "./pptx-viewer-cache"
import {
  getPptxBitmapCacheKey,
  type PptxBitmapCacheInput,
  type PptxSize,
} from "./pptx-viewer-core"
import {
  createPptxRenderer,
  PptxRendererError,
  type PptxRenderer,
} from "./pptx-viewer-renderer"

const PPTX_SOURCE_CACHE_MAX = 4
const PPTX_BITMAP_CACHE_MAX = 8

export type PptxSourceRelease = () => void

export interface PptxSourceRenderInput extends PptxBitmapCacheInput {
  canvas: HTMLCanvasElement
  isLive?: () => boolean
}

export type PptxRenderResult =
  | { status: "rendered" }
  | { status: "cancelled" }
  | { status: "failed"; error: PptxRendererError }

export interface PptxSource extends Disposable {
  slideCount: number
  baseSize: PptxSize
  renderSlide(input: PptxSourceRenderInput): Promise<PptxRenderResult>
  hasBitmap(input: PptxBitmapCacheInput): boolean
  retain(): PptxSourceRelease
}

class RendererSource implements PptxSource {
  readonly slideCount: number
  readonly baseSize: PptxSize

  private readonly bitmaps = new DisposableLruCache<string, PptxBitmapEntry>(
    PPTX_BITMAP_CACHE_MAX
  )
  private queue: Promise<unknown> = Promise.resolve()
  private retainCount = 0
  private disposeRequested = false
  private disposed = false

  constructor(private readonly renderer: PptxRenderer) {
    this.slideCount = renderer.slideCount
    this.baseSize = renderer.baseSize
  }

  hasBitmap(input: PptxBitmapCacheInput) {
    return this.bitmaps.get(getPptxBitmapCacheKey(input)) !== undefined
  }

  renderSlide(input: PptxSourceRenderInput): Promise<PptxRenderResult> {
    if (this.disposed) {
      return Promise.resolve({
        status: "failed",
        error: new PptxRendererError(
          "disposed",
          "Presentation source was disposed."
        ),
      })
    }

    const cacheKey = getPptxBitmapCacheKey(input)
    const cached = this.bitmaps.get(cacheKey)
    if (cached) {
      if (!isRenderLive(input)) return Promise.resolve({ status: "cancelled" })
      drawBitmap(input.canvas, cached.bitmap)
      return Promise.resolve({ status: "rendered" })
    }

    const run = this.queue
      .catch(() => {})
      .then(async (): Promise<PptxRenderResult> => {
        if (!isRenderLive(input)) return { status: "cancelled" }

        try {
          await this.renderer.renderSlide(input)
        } catch (error) {
          return {
            status: "failed",
            error: normalizeRendererError(error),
          }
        }

        if (!isRenderLive(input)) return { status: "cancelled" }

        try {
          const bitmap = await createImageBitmap(input.canvas)
          if (!isRenderLive(input)) {
            bitmap.close()
            return { status: "cancelled" }
          }
          this.bitmaps.set(cacheKey, new PptxBitmapEntry(bitmap))
        } catch {
          /* Snapshot unsupported: the slide still rendered, just without cache. */
        }

        return { status: "rendered" }
      })

    this.queue = run.catch(() => {})
    return run
  }

  retain(): PptxSourceRelease {
    if (this.disposed) return () => {}
    this.retainCount += 1
    let released = false
    return () => {
      if (released) return
      released = true
      this.retainCount -= 1
      if (this.retainCount === 0 && this.disposeRequested) this.close()
    }
  }

  dispose() {
    this.disposeRequested = true
    if (this.retainCount === 0) this.close()
  }

  private close() {
    if (this.disposed) return
    this.disposed = true
    this.bitmaps.clear()
    this.renderer.dispose()
  }
}

class SourceCacheEntry implements Disposable {
  source?: PptxSource
  disposed = false

  constructor(readonly promise: Promise<PptxSource>) {
    promise.then(
      (source) => {
        this.source = source
        if (this.disposed) source.dispose()
      },
      () => {
        /* rejected entries are removed by getPptxSource */
      }
    )
  }

  dispose() {
    this.disposed = true
    this.source?.dispose()
  }
}

const sourceCache = new DisposableLruCache<string, SourceCacheEntry>(
  PPTX_SOURCE_CACHE_MAX
)

export function getPptxSource(src: string): Promise<PptxSource> {
  const cached = sourceCache.get(src)
  if (cached) return cached.promise

  const pendingEntry: { current?: SourceCacheEntry } = {}
  const promise = createPptxRenderer(src).then(
    (renderer) => new RendererSource(renderer),
    (error) => {
      if (
        pendingEntry.current &&
        sourceCache.get(src) === pendingEntry.current
      ) {
        sourceCache.delete(src)
      }
      throw error
    }
  )
  const entry = new SourceCacheEntry(promise)
  pendingEntry.current = entry
  sourceCache.set(src, entry)
  return entry.promise
}

export function disposePptxSourceCache() {
  sourceCache.clear()
}

function isRenderLive({ isLive }: Pick<PptxSourceRenderInput, "isLive">) {
  return !isLive || isLive()
}

function drawBitmap(canvas: HTMLCanvasElement, bitmap: ImageBitmap) {
  canvas.width = bitmap.width
  canvas.height = bitmap.height
  canvas.getContext("2d")?.drawImage(bitmap, 0, 0)
}

function normalizeRendererError(error: unknown) {
  if (error instanceof PptxRendererError) return error
  return new PptxRendererError(
    "render_failed",
    "Failed to render slide.",
    error
  )
}

"use client"

import * as React from "react"

import { ScrollArea } from "@/components/ui/scroll-area"
import { Skeleton } from "@/components/ui/skeleton"

import {
  getScaledSlideSize,
  getVisibleSlideSize,
  type PptxSize,
  type PptxSlideOverlayProps,
} from "./pptx-viewer-core"
import { type PptxScrollActivity } from "./pptx-viewer-scroll"
import { type PptxSource } from "./pptx-viewer-source"

type SlideRenderState = "idle" | "rendering" | "rendered" | "failed"

export interface PptxSlideScrollerProps {
  source: PptxSource
  zoomScale: number
  rotation: number
  eager: boolean
  activity: PptxScrollActivity
  renderSlideOverlay?: (props: PptxSlideOverlayProps) => React.ReactNode
  containerRef: React.Ref<HTMLDivElement>
  viewportRef: React.Ref<HTMLDivElement>
  onScroll: () => void
}

export function PptxSlideScroller({
  source,
  zoomScale,
  rotation,
  eager,
  activity,
  renderSlideOverlay,
  containerRef,
  viewportRef,
  onScroll,
}: PptxSlideScrollerProps) {
  return (
    <ScrollArea
      className="min-h-0 flex-1"
      viewportRef={viewportRef}
      viewportProps={{ onScroll }}
    >
      <div ref={containerRef} className="flex flex-col items-center gap-4 p-4">
        {Array.from({ length: source.slideCount }, (_, slideIndex) => (
          <PptxSlideFrame
            key={slideIndex}
            source={source}
            slideIndex={slideIndex}
            zoomScale={zoomScale}
            rotation={rotation}
            eager={eager}
            activity={activity}
            renderSlideOverlay={renderSlideOverlay}
          />
        ))}
      </div>
    </ScrollArea>
  )
}

function PptxSlideFrame({
  source,
  slideIndex,
  zoomScale,
  rotation,
  eager,
  activity,
  renderSlideOverlay,
}: {
  source: PptxSource
  slideIndex: number
  zoomScale: number
  rotation: number
  eager: boolean
  activity: PptxScrollActivity
  renderSlideOverlay?: (props: PptxSlideOverlayProps) => React.ReactNode
}) {
  const [isNearViewport, setIsNearViewport] = React.useState(false)

  const frameRef = React.useCallback((element: HTMLDivElement | null) => {
    if (!element) return
    const root = element.closest<HTMLElement>(
      '[data-slot="scroll-area-viewport"]'
    )
    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) setIsNearViewport(entry.isIntersecting)
      },
      { root, rootMargin: "150% 0px" }
    )
    observer.observe(element)
    return () => observer.disconnect()
  }, [])

  const slideSize = getScaledSlideSize(source.baseSize, zoomScale)
  const visibleSize = getVisibleSlideSize(slideSize, rotation)

  return (
    <div
      ref={frameRef}
      className="relative shadow-sm ring-1 ring-border"
      style={{ width: visibleSize.width, height: visibleSize.height }}
      data-slot="pptx-slide"
      data-slide-number={slideIndex + 1}
    >
      <div
        className="absolute top-1/2 left-1/2"
        style={{
          width: slideSize.width,
          height: slideSize.height,
          transform: `translate(-50%, -50%) rotate(${rotation}deg)`,
        }}
      >
        {isNearViewport ? (
          <PptxSlideCanvas
            source={source}
            slideIndex={slideIndex}
            zoomScale={zoomScale}
            eager={eager}
            activity={activity}
          />
        ) : (
          <Skeleton className="size-full rounded-none" />
        )}
      </div>
      {renderSlideOverlay ? (
        <PptxSlideOverlay
          slideNumber={slideIndex + 1}
          visibleSize={visibleSize}
          zoomScale={zoomScale}
          rotation={rotation}
          renderSlideOverlay={renderSlideOverlay}
        />
      ) : null}
    </div>
  )
}

function PptxSlideCanvas({
  source,
  slideIndex,
  zoomScale,
  eager,
  activity,
}: {
  source: PptxSource
  slideIndex: number
  zoomScale: number
  eager: boolean
  activity: PptxScrollActivity
}) {
  const dpr = (typeof window !== "undefined" ? window.devicePixelRatio : 1) || 1
  const slideSize = getScaledSlideSize(source.baseSize, zoomScale)
  const [renderState, setRenderState] = React.useState<SlideRenderState>("idle")

  const canvasRef = React.useCallback(
    (canvas: HTMLCanvasElement | null) => {
      if (!canvas) return
      let cancelled = false
      const renderScale = zoomScale * dpr
      setRenderState("rendering")

      const start = () => {
        source
          .renderSlide({
            slideIndex,
            canvas,
            renderScale,
            isLive: () => !cancelled,
          })
          .then((result) => {
            if (cancelled) return
            if (result.status === "cancelled") return
            setRenderState(result.status === "failed" ? "failed" : "rendered")
          })
      }

      if (
        eager ||
        source.hasBitmap({ slideIndex, renderScale }) ||
        !activity.isScrolling()
      ) {
        start()
        return () => {
          cancelled = true
        }
      }

      const off = activity.onIdle(() => {
        if (!cancelled) start()
      })
      return () => {
        cancelled = true
        off()
      }
    },
    [activity, dpr, eager, zoomScale, slideIndex, source]
  )

  return (
    <>
      <canvas
        ref={canvasRef}
        style={{ width: slideSize.width, height: slideSize.height }}
        className="block h-full w-full bg-white"
      />
      {renderState === "failed" ? (
        <div className="absolute inset-0 flex items-center justify-center bg-muted p-4 text-center text-xs text-muted-foreground">
          Couldn&apos;t render slide {slideIndex + 1}.
        </div>
      ) : null}
      {renderState !== "rendered" && renderState !== "failed" ? (
        <Skeleton className="pointer-events-none absolute inset-0 rounded-none" />
      ) : null}
    </>
  )
}

function PptxSlideOverlay({
  slideNumber,
  visibleSize,
  zoomScale,
  rotation,
  renderSlideOverlay,
}: {
  slideNumber: number
  visibleSize: PptxSize
  zoomScale: number
  rotation: number
  renderSlideOverlay: (props: PptxSlideOverlayProps) => React.ReactNode
}) {
  return (
    <div className="pointer-events-none absolute inset-0">
      {renderSlideOverlay({
        slideNumber,
        width: visibleSize.width,
        height: visibleSize.height,
        scale: zoomScale,
        rotation,
      })}
    </div>
  )
}

